-- OPTIONAL TEACHING EXAMPLE, NOT THE VERIFIED FEI RSS SCHEMA.
-- Discover the source relation and columns using 03_validate_data.sql first.
-- Replace source schema/table below. Assumes standard, unquoted Snowflake names:
-- TITLE, URL, DATE and _FIVETRAN_SYNCED. Adjust names and date format to real data.
-- Prefer separate transformed schemas; do not edit Fivetran-managed source tables.
USE ROLE ACCOUNTADMIN;
USE WAREHOUSE COMPUTE_WH;
CREATE DATABASE IF NOT EXISTS FEI;
CREATE SCHEMA IF NOT EXISTS FEI.BRONZE;
CREATE SCHEMA IF NOT EXISTS FEI.SILVER;
CREATE SCHEMA IF NOT EXISTS FEI.GOLD;

CREATE OR REPLACE VIEW FEI.BRONZE.FEI_RSS AS
SELECT TITLE::VARCHAR AS TITLE_TEXT,
       URL::VARCHAR AS URL_TEXT,
       DATE::VARCHAR AS PUBLISHED_AT_TEXT,
       _FIVETRAN_SYNCED AS INGESTED_AT
FROM FIVETRAN_DATABASE.REPLACE_SOURCE_SCHEMA.REPLACE_SOURCE_TABLE;

CREATE OR REPLACE VIEW FEI.SILVER.FEI_RSS AS
SELECT NULLIF(TRIM(TITLE_TEXT), '') AS TITLE,
       NULLIF(TRIM(URL_TEXT), '') AS URL,
       TRY_TO_TIMESTAMP_NTZ(PUBLISHED_AT_TEXT) AS PUBLISHED_AT,
       INGESTED_AT
FROM FEI.BRONZE.FEI_RSS;
-- TRY parsing preserves the row while returning NULL for an invalid timestamp.
-- NTZ deliberately discards zone context. Use TZ/explicit formats if needed.

CREATE OR REPLACE VIEW FEI.GOLD.FEI_RSS_DAILY AS
SELECT TO_DATE(PUBLISHED_AT) AS PUBLICATION_DATE, COUNT(*) AS ARTICLE_COUNT
FROM FEI.SILVER.FEI_RSS
WHERE PUBLISHED_AT IS NOT NULL
GROUP BY TO_DATE(PUBLISHED_AT);

SELECT COUNT(*) AS INVALID_OR_MISSING_PUBLICATION_DATES
FROM FEI.SILVER.FEI_RSS WHERE PUBLISHED_AT IS NULL;
SELECT URL, COUNT(*) AS COPIES
FROM FEI.SILVER.FEI_RSS GROUP BY URL HAVING COUNT(*) > 1;
SELECT * FROM FEI.GOLD.FEI_RSS_DAILY ORDER BY PUBLICATION_DATE DESC;
-- Views do not preserve history removed from the Sheet. Design snapshots separately.
